def predict(board, action):
    if isinstance(action, tuple):
        row, col = action
    else:
        row, col = action[0], action[1]

    if board[row][col] == 'B':
        neighbors = [
            (row-1, col), (row+1, col),
            (row, col-1), (row, col+1)
        ]
        changes = set()

        for nr, nc in neighbors:
            if 0 <= nr < 64 and 0 <= nc < 64 and board[nr][nc] == 'B':
                changes.add((nr, nc))

        for r, c in changes:
            board[r][c] = 'g' if (r, c) != (row, col) else 'p'
    else:
        return board

    return [''.join(row) for row in board]
